-- SkillSprint catalogue expansion: three additional technical learning paths
-- and 30 published multiple-choice lessons. Answer keys remain private.
insert into public.learning_paths(id,title,description,level,sort_order,metadata,is_published)
values
('mobile','Mobile App Development','Build useful Android and iOS experiences with modern app fundamentals.','Beginner',6,'{"color":"blue","icon":"phone"}'::jsonb,true),
('cloud','Cloud & DevOps','Understand deployment, automation, containers and cloud infrastructure.','Beginner',7,'{"color":"cyan","icon":"activity"}'::jsonb,true),
('design','UI/UX & Product Design','Create accessible, usable interfaces and validate product decisions.','Beginner',8,'{"color":"pink","icon":"sparkle"}'::jsonb,true)
on conflict(id) do update set title=excluded.title,description=excluded.description,level=excluded.level,sort_order=excluded.sort_order,metadata=excluded.metadata,is_published=true,updated_at=now();

do $catalogue$
declare q record;
begin
 for q in select * from (values
 -- Mobile app development: Flutter fundamentals (5)
 ('mobile-flutter-01','mobile',1,'Flutter fundamentals','Understand a Flutter widget','Flutter builds interfaces from composable widgets.','What is the basic building block of a Flutter user interface?','A widget','A database row','A CSS selector','A network socket','a','Flutter user interfaces are composed from widgets.','Think of the reusable building blocks that describe the UI.'),
 ('mobile-flutter-02','mobile',2,'Flutter fundamentals','Choose a stateless widget','Stateless widgets describe UI that does not manage mutable local state.','Which Flutter class is appropriate for a widget with no mutable local state?','StatefulWidget','StatelessWidget','StreamBuilder only','MaterialApp only','b','StatelessWidget is used when the widget does not need mutable state of its own.','Choose the widget class whose name indicates no mutable state.'),
 ('mobile-flutter-03','mobile',3,'Flutter fundamentals','Identify the app entry point','A Flutter app commonly starts by calling runApp.','Which function attaches the root widget to the Flutter framework?','mainView()','runApp()','startWidget()','buildRoot()','b','runApp takes the root widget and starts the Flutter application.','It is the function commonly called from main().' ),
 ('mobile-flutter-04','mobile',4,'Flutter fundamentals','Arrange widgets vertically','Column lays out its children vertically.','Which Flutter layout widget places children from top to bottom?','Row','Stack','Column','Wrap','c','Column arranges children along the vertical axis.','Choose the layout widget that is the vertical counterpart of Row.'),
 ('mobile-flutter-05','mobile',5,'Flutter fundamentals','Handle a button tap','Button callbacks connect user actions to application logic.','Which property is commonly used to handle a Flutter button press?','onPressed','onHoverOnly','tapTarget','onRoute','a','onPressed receives the callback invoked when the button is activated.','Look for the callback property named for a press.'),
 -- Mobile app development: mobile platform and state (5)
 ('mobile-state-01','mobile',6,'Mobile app state','Update state in a StatefulWidget','Calling setState tells Flutter to rebuild after local state changes.','What should a StatefulWidget state object call after changing a value used by build()?','repaintNow()','setState()','refreshTree()','notifyRoute()','b','setState schedules a rebuild so the UI reflects the changed state.','Use the state notification method supplied by Flutter.'),
 ('mobile-state-02','mobile',7,'Mobile app state','Persist small local preferences','Key-value storage is suitable for small preferences such as theme choice.','Which kind of data is best suited to local key-value preferences?','A multi-gigabyte video archive','A theme setting and onboarding flag','A relational analytics warehouse','A public image CDN','b','Small settings and flags are typical key-value preference data.','Think of a simple setting rather than large structured data.'),
 ('mobile-state-03','mobile',8,'Mobile app state','Choose responsive layout behaviour','Responsive layouts adapt to available screen constraints.','Which value is most useful when deciding whether a mobile layout should switch to a wider arrangement?','Available screen width','The phone battery percentage','The current ringtone','The app icon file size','a','Available width is a direct layout constraint and can guide responsive breakpoints.','Choose the measurement that determines how much horizontal space the UI has.'),
 ('mobile-state-04','mobile',9,'Mobile app state','Request a network response safely','Network requests can fail and should expose loading and error states.','What should a mobile screen show while an asynchronous request is still pending?','A success message before data arrives','A loading state','An empty crash screen','A permanent disabled interface','b','A loading state communicates that work is in progress while awaiting the response.','Make the pending state visible to the user.'),
 ('mobile-state-05','mobile',10,'Mobile app state','Protect sensitive local data','Sensitive tokens should not be stored as plain text in general preferences.','Where should a mobile app store a sensitive authentication token?','A public text file','A screenshot folder','Platform-provided secure storage','The app display name','c','Platform secure storage uses OS-backed protection for secrets.','Use the secure storage facility provided by the platform.'),
 -- Cloud and DevOps: deployment basics (5)
 ('cloud-deploy-01','cloud',1,'Deployment basics','Understand a deployment','Deployment makes a built application available in a target environment.','What does deploying a web application normally mean?','Making the application available in a target environment','Renaming every source file','Deleting its dependencies','Changing the developer username','a','Deployment publishes or installs the application into an environment where it can run.','Think about moving a build into an environment where users can access it.'),
 ('cloud-deploy-02','cloud',2,'Deployment basics','Separate environments','Development, staging and production environments reduce release risk.','Which environment is commonly used for final pre-release testing?','Production only','Staging','A developer downloads folder','The browser cache','b','Staging mirrors production closely and is used for release verification.','Choose the environment immediately before production.'),
 ('cloud-deploy-03','cloud',3,'Deployment basics','Recognize continuous integration','CI automatically builds and tests changes when code is integrated.','What is the main purpose of continuous integration?','Run automated checks as code changes are integrated','Replace version control','Guarantee that code has no defects','Store customer passwords','a','CI provides repeatable automated builds and tests on integrated changes.','Think automated build and test on each change.'),
 ('cloud-deploy-04','cloud',4,'Deployment basics','Keep secrets out of source control','Environment variables and secret stores keep credentials out of committed source.','Where should a production API secret be kept?','Inside a public JavaScript file','In a committed README','In the deployment platform secret store','In a CSS comment','c','A secret manager or protected deployment environment variable avoids exposing credentials in source control.','Do not commit the secret with application code.'),
 ('cloud-deploy-05','cloud',5,'Deployment basics','Read a failed health check','Health checks help determine whether a service is ready to receive traffic.','What should a load balancer do when an instance repeatedly fails its health check?','Send more traffic to it','Temporarily stop routing traffic to it','Delete the source repository','Disable all monitoring','b','Unhealthy instances should be removed from rotation until they recover.','Protect users from an instance that is not healthy.'),
 -- Cloud and DevOps: containers and automation (5)
 ('cloud-container-01','cloud',6,'Containers & automation','Understand a container image','An image is a packaged template used to create containers.','In Docker, what is an image?','A running process only','A packaged template used to create containers','A cloud billing invoice','A network firewall rule','b','A container image contains the filesystem and metadata used to instantiate a container.','It is the package from which containers are created.'),
 ('cloud-container-02','cloud',7,'Containers & automation','Build an image','A Dockerfile describes steps for building an image.','Which file commonly defines instructions for building a Docker image?','Dockerfile','package-lock.json','robots.txt','manifest.csv','a','Docker uses a Dockerfile as a build instruction file.','Choose the conventional Docker build definition file.'),
 ('cloud-container-03','cloud',8,'Containers & automation','Persist container data','Volumes provide storage that can outlive a container instance.','Why attach a volume to a database container?','To make the container run faster by default','To persist database files beyond the container lifecycle','To replace SQL queries','To expose source code publicly','b','A volume stores data outside the writable container layer and can survive container replacement.','Think persistence when the container is recreated.'),
 ('cloud-container-04','cloud',9,'Containers & automation','Automate a repeatable task','Automation reduces manual variation in repeatable operational work.','Which task is a strong candidate for CI automation?','Manually choosing a logo colour','Running unit tests on each pull request','Writing a one-time meeting note','Changing a monitor brightness','b','Automated tests on pull requests provide consistent feedback before merging.','Choose the repeatable software quality check.'),
 ('cloud-container-05','cloud',10,'Containers & automation','Monitor service reliability','Logs, metrics and traces provide complementary operational signals.','Which signal is best for tracking request latency over time?','Metrics','A logo image','A source-code comment','A user avatar','a','Metrics capture numeric measurements such as latency and request rate over time.','Choose the time-series numeric signal.'),
 -- UI/UX and product design: interface foundations (5)
 ('design-ui-01','design',1,'Interface foundations','Understand visual hierarchy','Visual hierarchy guides attention to the most important content.','Which technique most directly helps establish visual hierarchy?','Making every element the same size','Using deliberate size, contrast and spacing differences','Removing all headings','Using random alignment','b','Hierarchy is created through intentional differences in scale, contrast, position and spacing.','Think about how a design guides the eye.'),
 ('design-ui-02','design',2,'Interface foundations','Use consistent spacing','A spacing scale creates rhythm and reduces arbitrary layout decisions.','Why use a consistent spacing scale in a design system?','To make every page identical','To create predictable rhythm and alignment','To prevent responsive layouts','To remove all whitespace','b','A spacing scale creates consistent relationships between components and sections.','Choose the reason connected to rhythm and alignment.'),
 ('design-ui-03','design',3,'Interface foundations','Design accessible contrast','Text contrast affects readability for users with low vision.','What should be checked when choosing text and background colours?','Whether both colours are fashionable','Their contrast ratio','The file extension','The number of page sections','b','Contrast ratio is a measurable accessibility requirement for readable text.','Check the measurable relationship between foreground and background.'),
 ('design-ui-04','design',4,'Interface foundations','Choose a clear primary action','A screen should make its main action easy to identify.','A form has one main task. How should its primary action be presented?','As the clearest, most prominent action','As an unlabeled icon','Hidden below unrelated links','With the same emphasis as every secondary action','a','A clear primary action communicates the next step and reduces decision friction.','Make the main task visually obvious.'),
 ('design-ui-05','design',5,'Interface foundations','Design for mobile touch','Touch targets need sufficient size and separation.','Why should mobile buttons have comfortable touch target sizes?','To increase the page download size','To reduce accidental taps and improve accessibility','To make text harder to read','To remove keyboard support','b','Adequate touch targets improve motor accessibility and reduce accidental activation.','Consider users tapping with a finger rather than a mouse.'),
 -- UI/UX and product design: research and validation (5)
 ('design-research-01','design',6,'Research & validation','Interview users neutrally','Neutral questions reduce the risk of leading participants.','Which interview question is least leading?','You love this feature, right?','Would you agree this is easier?','Tell me about the last time you completed this task.','Is our design perfect?','c','Asking about a recent real experience encourages specific evidence without suggesting an answer.','Ask about past behaviour rather than asking for agreement.'),
 ('design-research-02','design',7,'Research & validation','Use a usability test','Usability testing observes people attempting realistic tasks.','What is the main purpose of a usability test?','To observe whether users can complete tasks with the product','To measure the developer typing speed','To choose a company name','To replace all analytics','a','Usability testing reveals where users struggle while completing representative tasks.','Observe people using the product to complete tasks.'),
 ('design-research-03','design',8,'Research & validation','Interpret a prototype','A prototype helps test an idea before full implementation.','What is a key advantage of testing a clickable prototype early?','It guarantees production performance','It exposes flow and interaction problems before expensive implementation','It removes the need for users','It automatically creates the database','b','Prototypes make flows testable before committing to full implementation.','Think about finding interaction problems before coding everything.'),
 ('design-research-04','design',9,'Research & validation','Prioritize a usability issue','Severity depends on impact and how often a problem occurs.','Which issue should usually be fixed first?','A typo in a rarely visited footer','A sign-in blocker affecting most users','A minor shadow mismatch','A decorative icon offset by one pixel','b','A widespread blocker prevents the core task and has high user impact.','Prioritize a problem that prevents many users from completing a core task.'),
 ('design-research-05','design',10,'Research & validation','Validate a design change','A useful design iteration checks whether the change improved the outcome.','After changing a checkout flow, what is the strongest validation approach?','Assume the new design is better','Test the same key task and compare completion and error evidence','Only ask the designer','Change several unrelated things at once','b','Testing the same task with relevant measures provides evidence about the change.','Compare the task outcome before and after the change.')
 ) as bank(id,path_id,sort_order,category,title,body,question,a,b,c,d,answer,explanation,hint)
 loop
   insert into public.lessons(id,path_id,type,category,title,subtitle,body,content,reward_xp,sort_order,is_published)
   values(q.id,q.path_id,'multiple_choice',q.category,q.title,'Guided practice · Beginner',q.body,
     jsonb_build_object('question',q.question,'options',jsonb_build_array(jsonb_build_object('id','a','label',q.a),jsonb_build_object('id','b','label',q.b),jsonb_build_object('id','c','label',q.c),jsonb_build_object('id','d','label',q.d)),'explanation',q.explanation,'hint',q.hint,'difficulty','beginner'),25,q.sort_order,true)
   on conflict(id) do update set path_id=excluded.path_id,category=excluded.category,title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,content=excluded.content,sort_order=excluded.sort_order,is_published=true,updated_at=now();
   insert into public.lesson_answer_keys(lesson_id,correct_answer)
   values(q.id,to_jsonb(q.answer::text))
   on conflict(lesson_id) do update set correct_answer=excluded.correct_answer;
 end loop;
end
$catalogue$;

-- Index supports ordered topic queues and category browsing.
create index if not exists lessons_path_category_sort_idx
  on public.lessons(path_id,category,sort_order,id) where is_published;


-- SkillSprint curriculum expansion: add 15 new questions to each of the six topics
-- introduced in the mobile, cloud and design learning paths.
-- The migration is idempotent; answer keys remain in the private answer-key table.

do $expand_questions$
declare
  q record;
begin
  for q in
    select * from (values
      ('mobile-flutter-06','mobile',11,'Flutter fundamentals','Explain widget composition','Flutter widgets can contain child widgets to form a UI tree.','What does nesting widgets allow a Flutter developer to do?','Compose complex interfaces from smaller widgets','Store SQL tables inside widgets','Compile Dart into CSS','Replace the operating system','a','Widget composition builds larger interfaces from reusable smaller pieces.','Think about how a widget tree is assembled.'),
      ('mobile-flutter-07','mobile',12,'Flutter fundamentals','Use a MaterialApp root','MaterialApp provides app-level Material Design configuration and navigation support.','What is a common role of MaterialApp near the root of a Flutter app?','Define app-wide Material configuration and routing','Save passwords to secure storage','Create a database schema','Run a background server','a','MaterialApp configures application-wide Material behaviour such as themes and navigation.','It commonly wraps the root screen.'),
      ('mobile-flutter-08','mobile',13,'Flutter fundamentals','Identify the build method','The build method describes the widget subtree for the current configuration and state.','Which method describes the UI returned by a Flutter widget?','renderNow()','build()','composeTree()','drawScreen()','b','Flutter calls build to obtain the widget subtree for the current state.','It is the method that returns a Widget.'),
      ('mobile-flutter-09','mobile',14,'Flutter fundamentals','Pass data to a child widget','Constructor parameters commonly pass configuration and data into widgets.','How should a parent commonly provide a title to a reusable child widget?','Through a constructor parameter','By editing the child source file at runtime','Through a global database password','By changing the device hostname','a','Constructor parameters make widget inputs explicit and reusable.','Pass the value when creating the child.'),
      ('mobile-flutter-10','mobile',15,'Flutter fundamentals','Choose a list widget','ListView builds a scrollable list of widgets.','Which Flutter widget is commonly used for a vertically scrollable list?','GridPaper','ListView','Positioned','Divider','b','ListView provides a scrollable linear collection of child widgets.','Choose the widget named for a list.'),
      ('mobile-flutter-11','mobile',16,'Flutter fundamentals','Understand hot reload','Hot reload injects code changes while preserving much of the current app state.','What is the main benefit of Flutter hot reload during development?','Apply many code changes quickly without a full restart','Publish the app to an app store','Reset every database','Replace Dart with JavaScript','a','Hot reload speeds UI iteration by updating code in the running app.','It shortens the edit-and-see cycle.'),
      ('mobile-flutter-12','mobile',17,'Flutter fundamentals','Separate widget configuration from state','A StatefulWidget configuration is immutable; its State object holds mutable state.','Where does mutable local state for a StatefulWidget normally live?','Inside its State object','Inside pubspec.yaml','Inside the widget constructor after creation','Inside the Android manifest','a','The State object owns mutable values and lifecycle behaviour for the widget.','Distinguish the widget configuration from its State.'),
      ('mobile-flutter-13','mobile',18,'Flutter fundamentals','Use const constructors','Const widgets can reduce unnecessary object creation when their inputs are compile-time constants.','When is const appropriate for a Flutter widget?','When its constructor arguments are compile-time constants','Whenever the widget makes an HTTP request','Only when it contains a database','When it changes every frame','a','Const construction is valid when the widget and its arguments are constant expressions.','Check whether the inputs are known at compile time.'),
      ('mobile-flutter-14','mobile',19,'Flutter fundamentals','Understand Scaffold','Scaffold supplies a standard visual structure for Material Design screens.','Which widget provides common screen structure such as app bar, body and floating action button?','Scaffold','GestureDetector','ContainerBuilder','NavigatorObserver','a','Scaffold implements the common visual layout structure for a Material screen.','Think of the standard page frame.'),
      ('mobile-flutter-15','mobile',20,'Flutter fundamentals','Handle taps accessibly','InkWell provides Material tap feedback and gesture handling.','Which widget is often used to make a Material child respond to taps with ripple feedback?','InkWell','SafeArea','Expanded','MediaQuery','a','InkWell detects taps and provides Material ink reactions.','Choose the Material interaction widget.'),
      ('mobile-flutter-16','mobile',21,'Flutter fundamentals','Use Expanded in a Row','Expanded makes a child fill available main-axis space in a Flex layout.','What does Expanded do when placed inside a Row?','Uses available horizontal space according to its flex','Makes text bold','Adds a route to Navigator','Makes the row scroll vertically','a','Expanded allocates remaining main-axis space to its child.','In a Row, the main axis is horizontal.'),
      ('mobile-flutter-17','mobile',22,'Flutter fundamentals','Understand Navigator push','Navigator.push adds a route to the navigation stack.','What is the usual effect of Navigator.push in Flutter?','Open a new route above the current route','Delete the current app','Clear all widget state','Save a file to device storage','a','Pushing a route places a new page on top of the navigation stack.','Think of adding a page to the stack.'),
      ('mobile-flutter-18','mobile',23,'Flutter fundamentals','Read asynchronous results','Future represents a value or error that will become available later.','Which Dart type represents one eventual result of an asynchronous operation?','Stream','Future','Widget','BuildContext','b','A Future completes once with a value or an error.','It represents one result in the future.'),
      ('mobile-flutter-19','mobile',24,'Flutter fundamentals','Handle async errors','try/catch can handle errors thrown while awaiting a Future.','How can an async function handle an error from an awaited Future?','Wrap the await in try/catch','Put the await inside a CSS selector','Use const instead of final','Call build() twice','a','Awaited errors can be caught by the surrounding try/catch block.','Use Dart''s normal exception handling.'),
      ('mobile-flutter-20','mobile',25,'Flutter fundamentals','Declare package dependencies','pubspec.yaml lists Dart and Flutter package dependencies.','Where does a Flutter project declare package dependencies?','pubspec.yaml','analysis_options.lock','README.html','AndroidManifest.xml only','a','The pubspec manifest declares dependencies and project metadata.','Look for the Dart package manifest.'),
      ('mobile-state-06','mobile',11,'Mobile app state','Choose local preferences','Small non-sensitive settings can be stored as key-value preferences.','Which value is a suitable example for shared preferences?','The selected app theme','A full relational database backup','A private signing key','A video streaming archive','a','Preferences suit small values such as theme choice or onboarding completion.','Choose a small setting.'),
      ('mobile-state-07','mobile',12,'Mobile app state','Protect credentials','Authentication tokens should use platform-backed secure storage.','Why should an access token not be stored in ordinary preferences?','Ordinary preferences are not designed as secure secret storage','Preferences cannot store strings','Tokens must only be stored in images','It prevents the app from opening','a','Secure storage uses platform security facilities to protect sensitive credentials.','Distinguish settings storage from secret storage.'),
      ('mobile-state-08','mobile',13,'Mobile app state','Model loading state','A request state commonly distinguishes idle, loading, success and error.','Which state should a screen enter immediately after starting a data request?','Loading','Completed','Archived','Deleted','a','Loading communicates that the asynchronous operation is still in progress.','The response has not arrived yet.'),
      ('mobile-state-09','mobile',14,'Mobile app state','Handle empty results','An empty state explains that a successful query returned no items.','What should an app display when a request succeeds but returns no records?','A helpful empty state with a next step','A permanent loading spinner','A false error message','A blank screen with no context','a','An empty state distinguishes no data from a failure and guides the user.','The request succeeded; the collection is simply empty.'),
      ('mobile-state-10','mobile',15,'Mobile app state','Use an API status code','HTTP 401 indicates missing or invalid authentication credentials.','What does an HTTP 401 response usually indicate?','Authentication is required or invalid','The server created a resource','The request succeeded with no content','The server permanently moved the URL','a','401 is an authentication response, unlike 403 which indicates forbidden access.','Think about whether the client is authenticated.'),
      ('mobile-state-11','mobile',16,'Mobile app state','Handle offline mode','Offline-first apps keep useful local data and synchronize when connectivity returns.','What is a core offline-first behaviour?','Allow supported tasks with local data and sync changes later','Disable the app whenever Wi-Fi drops','Discard all unsent user changes','Require a fresh install after reconnecting','a','Offline-first design preserves useful functionality and reconciles queued changes later.','The app should remain useful without a network.'),
      ('mobile-state-12','mobile',17,'Mobile app state','Avoid duplicate submissions','Idempotency keys can prevent repeated network submissions from creating duplicate operations.','How can a client help prevent duplicate payment requests after a timeout?','Retry with the same idempotency key','Generate a new payment for every retry','Disable TLS','Send the user''s password in the URL','a','A stable idempotency key lets the server recognize retries as the same operation.','Keep the retry tied to the original operation.'),
      ('mobile-state-13','mobile',18,'Mobile app state','Respect lifecycle changes','Mobile apps may pause or resume as users switch apps or receive calls.','Why should an app account for lifecycle changes?','To manage resources and preserve appropriate state','To change the user''s email automatically','To bypass platform permissions','To force every screen to rebuild forever','a','Lifecycle handling helps pause work and restore a coherent experience.','Apps do not remain continuously foregrounded.'),
      ('mobile-state-14','mobile',19,'Mobile app state','Request permissions contextually','Permission prompts are clearer when shown near the feature that needs access.','When should an app request camera permission?','When the user starts a feature that needs the camera','Immediately on every launch without explanation','After deleting the camera feature','Only after the app crashes','a','Contextual requests explain the value of access and improve user understanding.','Ask when the user invokes the camera feature.'),
      ('mobile-state-15','mobile',20,'Mobile app state','Validate input on device','Client-side validation improves usability but must be repeated on the server.','Why should a backend validate data even when the mobile app validates it?','Clients can be modified or bypassed','Mobile validation is always encrypted','Servers cannot receive strings','It makes network requests faster automatically','a','Client checks are not a security boundary; untrusted requests can bypass them.','Assume the server can receive requests from other clients.'),
      ('mobile-state-16','mobile',21,'Mobile app state','Use pagination','Pagination retrieves large collections in manageable pages.','Why paginate a mobile feed with thousands of records?','Reduce initial transfer and memory use','Guarantee every record is always visible','Remove the need for authentication','Prevent all network failures','a','Pagination limits payload size and supports incremental loading.','Think about loading a smaller portion at a time.'),
      ('mobile-state-17','mobile',22,'Mobile app state','Cache static assets','Caching can reduce repeated downloads of images, fonts and other static assets.','What is a practical benefit of caching frequently used static assets?','Faster repeat access and lower network usage','Automatic database normalization','Stronger passwords','More accurate GPS coordinates','a','A local cache avoids downloading unchanged resources repeatedly.','The resource can be reused from local storage.'),
      ('mobile-state-18','mobile',23,'Mobile app state','Test on different screen sizes','Responsive layouts should adapt to varying dimensions and orientations.','Which test best checks a responsive mobile interface?','Test narrow and wide screens and relevant orientations','Test only one emulator size','Check only the app icon','Run a database migration','a','Multiple viewport sizes expose layout overflow and scaling issues.','Vary the available screen dimensions.'),
      ('mobile-state-19','mobile',24,'Mobile app state','Understand app signing','Release builds are signed to establish publisher identity and package integrity.','Why must an Android release package be signed?','To identify the publisher and support package integrity','To compress every image','To make the app open-source','To remove runtime permissions','a','Signing lets Android verify package updates and their signing identity.','Think about trusted package identity.'),
      ('mobile-state-20','mobile',25,'Mobile app state','Handle network timeouts','A timeout prevents a request from waiting indefinitely.','What should an app generally do when a network request times out?','Show a recoverable message and offer a safe retry','Pretend the request succeeded','Delete local user data','Retry rapidly without a limit','a','A bounded retry path and clear feedback help recover from temporary network failures.','Do not leave the user waiting forever.'),
      ('cloud-deploy-06','cloud',11,'Deployment basics','Use environment variables','Environment variables separate deployment configuration from application source.','Why use environment variables for deployment configuration?','Configure each environment without hard-coding values in source','Make source code publicly readable','Replace version control','Guarantee zero downtime','a','Environment variables let the same build use environment-specific settings.','Separate configuration from code.'),
      ('cloud-deploy-07','cloud',12,'Deployment basics','Understand rollback','A rollback restores a previously known-good release.','When is a rollback appropriate?','A new release causes a serious production regression','A developer changes a local font','A test passes successfully','A staging deployment is planned','a','Rollback quickly restores service while the regression is investigated.','Choose the response to a harmful production release.'),
      ('cloud-deploy-08','cloud',13,'Deployment basics','Use a health endpoint','A health endpoint reports whether a service is functioning or ready.','What is a readiness check intended to tell an orchestrator?','Whether an instance is ready to receive traffic','Whether a developer is online','Whether source files have comments','Whether the database has a logo','a','Readiness indicates whether an instance should be included in traffic routing.','It concerns serving requests now.'),
      ('cloud-deploy-09','cloud',14,'Deployment basics','Separate build and runtime','A build produces deployable artifacts; runtime executes them.','What is the purpose of a production build step?','Produce optimized artifacts intended for deployment','Create user accounts automatically','Replace application monitoring','Remove all source control history','a','Build tools transform source into artifacts suitable for production delivery.','Think of the deployable output.'),
      ('cloud-deploy-10','cloud',15,'Deployment basics','Use CI pipeline stages','A pipeline can run linting, tests, builds and deployment checks in sequence.','Which stage should normally block deployment when unit tests fail?','Automated test stage','Logo export stage','Documentation spelling stage only','User analytics stage','a','Failing tests should stop promotion of a release candidate.','Quality gates run before deployment.'),
      ('cloud-deploy-11','cloud',16,'Deployment basics','Protect production secrets','Production credentials belong in a protected secret manager or deployment settings.','Which practice best protects a production database password?','Store it in a protected secret manager','Commit it to a public repository','Place it in client-side JavaScript','Include it in a screenshot','a','Secret managers restrict access and avoid exposing credentials in source control.','Keep credentials out of public code.'),
      ('cloud-deploy-12','cloud',17,'Deployment basics','Understand DNS','DNS resolves domain names to records such as IP addresses.','What does a DNS A record map a hostname to?','An IPv4 address','A CSS stylesheet','A database table','An email attachment','a','An A record maps a hostname to an IPv4 address.','A is the address record for IPv4.'),
      ('cloud-deploy-13','cloud',18,'Deployment basics','Use HTTPS','HTTPS protects HTTP traffic with TLS.','What does TLS provide to an HTTPS connection?','Encryption and integrity, plus server authentication','A guarantee that the site content is truthful','Automatic malware removal','Unlimited bandwidth','a','TLS protects data in transit and authenticates the server certificate identity.','It secures the connection, not the honesty of content.'),
      ('cloud-deploy-14','cloud',19,'Deployment basics','Monitor error rates','Error-rate metrics reveal the proportion of failed requests.','Which metric helps detect a sudden rise in failed API requests?','HTTP 5xx rate','Logo download size','Number of CSS classes','Developer laptop battery','a','A rise in server-error responses can indicate a production incident.','Track the proportion of failed responses.'),
      ('cloud-deploy-15','cloud',20,'Deployment basics','Understand horizontal scaling','Horizontal scaling adds instances to share workload.','What does horizontal scaling normally mean for a web service?','Add more service instances','Increase one server''s RAM only','Reduce the number of users','Move every file to a laptop','a','Horizontal scaling increases capacity by adding instances.','Scale out rather than up.'),
      ('cloud-deploy-16','cloud',21,'Deployment basics','Use a reverse proxy','A reverse proxy receives client requests and forwards them to backend services.','What is a common role of a reverse proxy?','Route incoming requests to backend services','Compile Dart code','Store user passwords in plain text','Replace DNS globally','a','Reverse proxies can route traffic and provide TLS termination or load balancing.','It sits in front of backend services.'),
      ('cloud-deploy-17','cloud',22,'Deployment basics','Understand blue-green deployment','Blue-green deployment maintains two environments to support controlled traffic switching.','What is the key idea behind blue-green deployment?','Switch traffic between old and new production environments','Deploy only on weekends','Use two different programming languages','Disable monitoring during releases','a','The inactive environment receives the new release before traffic is switched.','Two environments allow a controlled cutover.'),
      ('cloud-deploy-18','cloud',23,'Deployment basics','Manage database migrations','Database migrations apply versioned schema changes across environments.','Why should database migrations be version-controlled?','Make schema changes repeatable and reviewable','Hide schema changes from developers','Automatically anonymize all user data','Replace database backups','a','Versioned migrations provide an auditable, repeatable schema history.','Treat schema changes like application code.'),
      ('cloud-deploy-19','cloud',24,'Deployment basics','Back up before risky changes','A tested backup supports recovery from accidental data loss.','What is the safest preparation before a risky production data migration?','Take and verify a recoverable backup and plan rollback','Delete the old data first','Disable access logs','Assume the migration cannot fail','a','A verified recovery point reduces the impact of migration failure.','Make sure recovery is possible before changing production data.'),
      ('cloud-deploy-20','cloud',25,'Deployment basics','Understand least privilege in CI','CI credentials should have only the permissions required for their task.','Why should a deployment token have limited permissions?','Reduce damage if the token is exposed','Make deployments slower','Allow every workflow to change billing','Avoid rotating credentials','a','Least-privilege tokens reduce the scope of a compromised credential.','Limit what the token can do.'),
      ('cloud-container-06','cloud',11,'Containers & automation','Distinguish container and image','A container is a running instance created from an image.','What is the relationship between a Docker image and a container?','An image is a template used to create a container','A container is a template used to compile an image','They are both network protocols','An image is always a running process','a','Images are packaged templates; containers are instantiated environments.','Think template versus running instance.'),
      ('cloud-container-07','cloud',12,'Containers & automation','Expose a container port','Port publishing maps a host port to a container port.','What does publishing a container port allow?','Host or external clients to reach a service in the container','The container to bypass all firewalls','The image to edit its Dockerfile','A volume to become a network','a','Port mapping forwards traffic from a host port to a container port.','It makes a container service reachable.'),
      ('cloud-container-08','cloud',13,'Containers & automation','Use a volume','A volume stores data outside a container''s writable layer.','Why use a named volume for a database container?','Keep database data across container replacement','Make the image smaller automatically','Expose the database to the public internet','Compile SQL into HTML','a','Named volumes persist data independently of a container instance.','Container replacement should not erase database files.'),
      ('cloud-container-09','cloud',14,'Containers & automation','Build reproducible images','Pinned base-image versions reduce unexpected changes during builds.','Why pin a base image to a known version or digest?','Improve build repeatability and supply-chain control','Guarantee the application has no bugs','Remove the need for patching','Make the image impossible to scan','a','Pinned inputs make image contents more predictable and auditable.','Avoid silently changing build inputs.'),
      ('cloud-container-10','cloud',15,'Containers & automation','Use multi-stage builds','Multi-stage builds separate build dependencies from the final runtime image.','What is a benefit of a multi-stage Docker build?','Keep build tools out of the final runtime image','Run two databases automatically','Avoid writing application tests','Make every container privileged','a','Only required runtime artifacts need to be copied into the final stage.','Separate compiling from running.'),
      ('cloud-container-11','cloud',16,'Containers & automation','Understand orchestration','Container orchestrators schedule and manage container workloads.','What is a common responsibility of Kubernetes?','Schedule and manage containerized workloads','Design application logos','Write SQL queries for every service','Replace application source control','a','Kubernetes coordinates deployment, scaling and lifecycle of container workloads.','It manages containers across a cluster.'),
      ('cloud-container-12','cloud',17,'Containers & automation','Use a container registry','Registries store and distribute container images.','Where should a team publish a versioned container image for deployment?','A container registry','A browser bookmark folder','A CSS variables file','A local recycle bin','a','A registry stores image artifacts so deployment systems can retrieve them.','Think of an image repository.'),
      ('cloud-container-13','cloud',18,'Containers & automation','Set resource limits','CPU and memory limits help prevent a workload from consuming excessive resources.','Why set memory limits for containers?','Prevent one workload from consuming unbounded host memory','Encrypt every network packet','Increase disk capacity automatically','Make application logs private','a','Resource limits help isolate workloads and protect node stability.','Control resource consumption.'),
      ('cloud-container-14','cloud',19,'Containers & automation','Use structured logs','Structured logs use consistent fields that tools can parse and query.','Which log format is easiest for log systems to filter by request_id?','Structured JSON records','Unlabelled paragraphs only','Screenshots of terminal output','A compressed audio file','a','Structured fields allow reliable filtering and correlation.','Choose machine-readable fields.'),
      ('cloud-container-15','cloud',20,'Containers & automation','Correlate distributed traces','Trace IDs connect spans belonging to one distributed request.','What does a trace ID help an engineer do?','Follow one request across multiple services','Identify the user''s screen resolution','Encrypt a container image','Choose a DNS registrar','a','A shared trace identifier links work across service boundaries.','It follows the same request through the system.'),
      ('cloud-container-16','cloud',21,'Containers & automation','Understand rolling updates','Rolling updates replace instances gradually while keeping a service available.','What is a benefit of a rolling deployment?','Update instances in stages instead of replacing all at once','Delete every previous release immediately','Disable health checks','Require users to reinstall the app','a','Gradual replacement can preserve service capacity during an update.','Only a portion is updated at a time.'),
      ('cloud-container-17','cloud',22,'Containers & automation','Automate repeatable builds','Build automation ensures the same steps run consistently.','Why automate container image builds in CI?','Produce consistent artifacts from reviewed source changes','Let each developer choose random commands','Avoid tracking image versions','Make the registry public','a','Automated builds improve consistency and traceability.','Repeat the same build process.'),
      ('cloud-container-18','cloud',23,'Containers & automation','Scan dependencies','Dependency scanners identify known vulnerabilities in packages and images.','What is a purpose of scanning a container image before release?','Find known vulnerable packages and components','Guarantee the container uses no CPU','Replace runtime monitoring','Create user passwords','a','Image scanning highlights known vulnerabilities for remediation.','Look for vulnerable components before shipping.'),
      ('cloud-container-19','cloud',24,'Containers & automation','Handle container shutdown','Processes should handle termination signals and shut down gracefully.','Why should a containerized service handle SIGTERM?','Allow graceful shutdown and cleanup','Force the host to reboot','Disable application authentication','Rebuild the image at runtime','a','Orchestrators commonly send termination signals before stopping a container.','Give the process time to finish safely.'),
      ('cloud-container-20','cloud',25,'Containers & automation','Keep containers non-root','Running as a non-root user limits privileges inside a container.','Why should an application container run as a non-root user when possible?','Reduce the impact of a process compromise','Make the container image larger','Avoid setting file permissions','Allow unrestricted host access','a','A non-root process has fewer privileges if the application is exploited.','Use the least privilege needed.'),
      ('design-ui-06','design',11,'Interface foundations','Use alignment','Consistent alignment creates visual order and makes scanning easier.','What is a benefit of aligning related form labels and fields consistently?','Improve scanning and visual structure','Increase server response time','Encrypt form values','Replace user testing','a','Alignment creates predictable relationships between elements.','Think about visual order.'),
      ('design-ui-07','design',12,'Interface foundations','Choose readable typography','Type scale and line length influence readability.','Which typography choice generally improves long-form readability on mobile?','Comfortable text size and moderate line length','Tiny text with very long lines','Using five unrelated font families','Removing paragraph spacing','a','Readable sizing and line lengths reduce visual strain and support scanning.','Prioritize legibility.'),
      ('design-ui-08','design',13,'Interface foundations','Use semantic controls','Semantic buttons communicate action and support keyboard and assistive technology interaction.','Why use a real button element for an action?','It provides built-in interaction semantics and keyboard support','It automatically stores the action in a database','It prevents all layout shifts','It makes the page load offline','a','Native buttons expose expected semantics and interaction behaviour.','Use the element designed for actions.'),
      ('design-ui-09','design',14,'Interface foundations','Provide focus indicators','Visible focus styles help keyboard users understand the current control.','What should happen when a user tabs to an interactive control?','A visible focus indicator should identify it','The control should disappear','The page should submit automatically','The mouse pointer should be hidden','a','Visible focus supports keyboard navigation and orientation.','Show which control currently has keyboard focus.'),
      ('design-ui-10','design',15,'Interface foundations','Design clear error messages','Useful errors identify the problem and suggest a recovery action.','Which error message is most useful after an invalid email entry?','Enter a valid email address, for example name@example.com','Error 17','Something happened','Invalid','a','Specific messages explain what needs correction and provide a helpful example.','State the problem and next action.'),
      ('design-ui-11','design',16,'Interface foundations','Use progressive disclosure','Progressive disclosure reveals advanced choices when they are relevant.','Why might a settings screen group advanced options under an expandable section?','Keep the initial interface focused while preserving access','Hide every important feature permanently','Increase the number of required steps','Prevent screen readers from reading settings','a','Progressive disclosure reduces initial complexity without removing functionality.','Show complexity when needed.'),
      ('design-ui-12','design',17,'Interface foundations','Maintain contrast','Contrast should be checked against accessibility guidelines for text and controls.','What should designers verify for normal-sized text?','That foreground and background contrast meets the applicable accessibility threshold','That the colours are both saturated','That the text is always bold','That the background is animated','a','Sufficient contrast supports users with low vision and improves readability.','Measure the text-to-background contrast.'),
      ('design-ui-13','design',18,'Interface foundations','Design touch targets','Larger separated touch targets reduce accidental activation.','What is a useful mobile design practice for adjacent icon buttons?','Provide adequate target size and spacing','Place them closer than one pixel','Remove accessible labels','Make only the icons visible on hover','a','Target size and spacing make controls easier to activate accurately.','Finger input needs room.'),
      ('design-ui-14','design',19,'Interface foundations','Show system status','Feedback helps users understand that an action has been received.','After a user taps Save, what should the interface do?','Show progress and then a success or error result','Remain unchanged indefinitely','Clear the form before sending','Navigate away without confirmation','a','Feedback confirms that the action was received and communicates its outcome.','Keep the user informed.'),
      ('design-ui-15','design',20,'Interface foundations','Avoid colour-only meaning','Icons, labels or patterns should supplement colour-coded states.','How should an error state be communicated to users who cannot distinguish its colour?','Use text or an icon in addition to colour','Use a brighter red only','Remove the error label','Flash the entire screen','a','Redundant cues make meaning available beyond colour perception.','Do not rely on colour alone.'),
      ('design-ui-16','design',21,'Interface foundations','Create responsive layouts','Fluid grids and breakpoints adapt interfaces to available space.','What should a responsive layout do when the viewport becomes narrow?','Reflow content to preserve readability and usable controls','Keep every desktop column at fixed width','Hide all navigation without replacement','Scale text down to unreadable sizes','a','Responsive layouts adapt structure to the constraints of the viewport.','Reorganize rather than simply shrink.'),
      ('design-ui-17','design',22,'Interface foundations','Use consistent components','Reusable components create predictable behaviour across screens.','Why reuse a shared button component across an application?','Maintain consistent states, spacing and interaction behaviour','Force every button to have the same label','Prevent all future design changes','Remove the need for accessibility testing','a','Shared components reduce visual and behavioural drift.','Consistency comes from shared implementation.'),
      ('design-ui-18','design',23,'Interface foundations','Understand affordance','Affordances and signifiers communicate how an element can be used.','Which visual treatment most clearly signals that text is a link?','A recognizable link style and clear label','A decorative background with no cue','A static paragraph with no interaction','A hidden click handler on an image','a','Recognizable styling and labels help users identify interactive text.','Make the action discoverable.'),
      ('design-ui-19','design',24,'Interface foundations','Design confirmation for destructive actions','Confirmation or undo can reduce accidental destructive operations.','For an irreversible delete action, what is a useful safeguard?','Clearly identify the item and require deliberate confirmation','Place Delete beside Save with identical styling','Trigger deletion on hover','Hide the item''s name','a','A clear confirmation helps users understand the consequence before deletion.','Make the consequence explicit.'),
      ('design-ui-20','design',25,'Interface foundations','Support reduced motion','Reduced-motion preferences help users avoid unnecessary animation.','How should an interface respond to a reduced-motion preference?','Reduce or remove non-essential motion effects','Increase parallax movement','Disable all keyboard input','Hide all content transitions by making text blink','a','Respecting reduced-motion settings improves comfort and accessibility.','Avoid unnecessary movement.'),
      ('design-research-06','design',11,'Research & validation','Recruit representative participants','Research participants should reflect the product''s intended users and contexts.','Why recruit participants who represent the target audience?','Find usability issues relevant to actual users','Guarantee every participant agrees with the design','Avoid collecting task evidence','Make the test shorter automatically','a','Representative participants reveal problems likely to affect the intended audience.','Match participants to the people who will use the product.'),
      ('design-research-07','design',12,'Research & validation','Write task-based scenarios','Usability tasks should describe goals without revealing the interface solution.','Which usability task is least leading?','Find and save a hostel listing that fits your budget','Tap the blue Save button at the top right','Click the exact menu item named Settings','Use the third card','a','A goal-based task lets participants discover the interface themselves.','Describe the outcome, not the steps.'),
      ('design-research-08','design',13,'Research & validation','Observe behaviour neutrally','Moderators should avoid coaching participants toward the expected answer.','During a usability test, what should a moderator do when a participant hesitates?','Ask what they are thinking without suggesting a control','Point to the correct button immediately','Complete the task for them','Tell them the design is easy','a','Neutral prompts preserve evidence about how participants interpret the interface.','Avoid steering the participant.'),
      ('design-research-09','design',14,'Research & validation','Distinguish qualitative and quantitative data','Qualitative data explains experiences; quantitative data measures amounts or rates.','Which is quantitative usability evidence?','Task completion rate','A participant''s description of confusion','A recorded interview quotation','An observer''s open-ended note','a','Completion rate is a numeric measure that can be compared across tests.','Choose a measurable number.'),
      ('design-research-10','design',15,'Research & validation','Measure task success','Task success should be defined before a usability study.','What should a usability team define before measuring task success?','The observable conditions that count as successful completion','The final colour palette','The developer''s preferred framework','The number of screens in the prototype','a','A clear success definition makes results consistent and interpretable.','Specify what successful completion means.'),
      ('design-research-11','design',16,'Research & validation','Prioritize findings by severity','Severity considers impact, frequency and ability to recover.','Which finding is usually highest severity?','Users cannot submit a required application form','A rarely seen icon is slightly misaligned','A footer has one extra pixel of padding','A decorative animation is slower than expected','a','A blocker in a core task has high impact on product use.','Prioritize failures that prevent essential tasks.'),
      ('design-research-12','design',17,'Research & validation','Use affinity mapping','Affinity mapping groups observations into themes.','What is the purpose of affinity mapping after interviews?','Cluster related observations to identify recurring themes','Calculate server uptime','Create final UI code automatically','Replace participant consent','a','Grouping related observations helps teams identify patterns across sessions.','Look for repeated themes in notes.'),
      ('design-research-13','design',18,'Research & validation','Avoid confirmation bias','Research should actively consider evidence that challenges assumptions.','How can a researcher reduce confirmation bias?','Use neutral questions and examine evidence that contradicts assumptions','Recruit only people who like the concept','Ignore negative observations','Change the success criteria after seeing results','a','Neutral methods and disconfirming evidence reduce selective interpretation.','Do not look only for support.'),
      ('design-research-14','design',19,'Research & validation','Test prototypes early','Low-fidelity prototypes can validate flow before visual polish.','Why test a low-fidelity prototype early?','Find structural and task-flow problems before detailed implementation','Measure production server throughput','Confirm final brand colours','Replace security testing','a','Early prototypes make it inexpensive to revise the basic interaction model.','Test the flow before polishing visuals.'),
      ('design-research-15','design',20,'Research & validation','Understand A/B testing','A/B tests compare variants using a defined outcome and suitable assignment.','What is essential for a meaningful A/B test?','A clear hypothesis, controlled variants and a defined metric','Changing several unrelated features for every user','Choosing the winner after one anecdote','Showing both variants to the same user at once','a','Controlled variants and predefined metrics support interpretable comparisons.','Keep the experiment focused.'),
      ('design-research-16','design',21,'Research & validation','Interpret sample limitations','Small or biased samples limit how broadly findings can be generalized.','What is a responsible conclusion from five usability sessions?','Identify observed usability issues without claiming population-wide statistical certainty','Claim that 100% of all users behave identically','Ignore every observation','Treat the sample as a national census','a','Small qualitative samples are useful for discovering issues but do not establish population estimates.','Match the claim to the evidence.'),
      ('design-research-17','design',22,'Research & validation','Use analytics responsibly','Analytics should collect only data needed for a legitimate product question.','What is a privacy-conscious analytics practice?','Collect minimal event data and avoid unnecessary personal identifiers','Record every keystroke by default','Store passwords in event properties','Share raw user sessions publicly','a','Data minimization reduces privacy risk while preserving useful product signals.','Collect only what the question needs.'),
      ('design-research-18','design',23,'Research & validation','Validate an iteration','A design change should be evaluated against the problem it intended to solve.','After redesigning a confusing sign-up flow, what should the team compare?','Completion and error rates for the same key tasks','The number of colours in each screen','The designer''s preferred layout','The file size of the logo only','a','Comparing the same task outcomes tests whether the redesign addressed the problem.','Measure the original problem again.'),
      ('design-research-19','design',24,'Research & validation','Document research findings','Research reports should distinguish observations, interpretations and recommendations.','Why separate observations from recommendations in a research report?','Make evidence and interpretation traceable','Make the report longer','Avoid mentioning limitations','Ensure every recommendation is treated as a fact','a','Separating evidence from interpretation makes conclusions easier to review.','Keep what happened distinct from what you propose.'),
      ('design-research-20','design',25,'Research & validation','Protect research participants','Informed consent explains participation and how collected information will be used.','What should participants receive before a recorded usability session?','An explanation of the study and informed consent choice','A guarantee that the product will launch','A request to share their account password','An instruction to ignore privacy notices','a','Informed consent supports ethical participation and transparent data handling.','Explain the study before recording.')
    ) as bank(id,path_id,sort_order,category,title,body,question,opt_a,opt_b,opt_c,opt_d,answer,explanation,hint)
  loop
    insert into public.lessons(
      id,path_id,type,category,title,subtitle,body,content,reward_xp,sort_order,is_published
    ) values (
      q.id,q.path_id,'multiple_choice',q.category,q.title,
      'Guided practice · Beginner',q.body,
      jsonb_build_object(
        'question',q.question,
        'options',jsonb_build_array(
          jsonb_build_object('id','a','label',q.opt_a),
          jsonb_build_object('id','b','label',q.opt_b),
          jsonb_build_object('id','c','label',q.opt_c),
          jsonb_build_object('id','d','label',q.opt_d)
        ),
        'explanation',q.explanation,
        'hint',q.hint,
        'difficulty','beginner',
        'review_weight',1
      ),
      25,q.sort_order,true
    )
    on conflict (id) do update set
      path_id=excluded.path_id,
      type=excluded.type,
      category=excluded.category,
      title=excluded.title,
      subtitle=excluded.subtitle,
      body=excluded.body,
      content=excluded.content,
      reward_xp=excluded.reward_xp,
      sort_order=excluded.sort_order,
      is_published=excluded.is_published,
      updated_at=now();

    insert into public.lesson_answer_keys(lesson_id,correct_answer)
    values(q.id,to_jsonb(q.answer::text))
    on conflict (lesson_id) do update
      set correct_answer=excluded.correct_answer;
  end loop;
end
$expand_questions$;
